use std::collections::HashMap;

use starstream_types::IntWidth;
use wasm_encoder::{BlockType, FuncType, InstructionSink, ValType};

use crate::{Compiler, StFunction};

/// Internal functions generated by the compiler.
#[derive(Default)]
pub struct Intrinsics {
    /// Overflow-checked arithmetic, by operation and width.
    checked: HashMap<(CheckedOp, IntWidth), u32>,
    /// Signed floored division and remainder, keyed by whether they're 64-bit.
    floored: HashMap<(FlooredOp, bool), u32>,
}

/// An integer operation that traps when its result doesn't fit its type.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CheckedOp {
    Add,
    Sub,
    Mul,
    /// Signed 8- and 16-bit floored division only: `MIN / -1` fits in the
    /// `i32` they're computed in. Wider types trap natively.
    Div,
}

/// A signed division operation, rounding the quotient toward negative
/// infinity as the spec requires, so the remainder has the divisor's sign.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum FlooredOp {
    Div,
    Rem,
}

impl Compiler {
    /// Get or create the function that computes `op` on two signed `width`
    /// integers. Division by zero and 32- and 64-bit `MIN / -1` trap natively;
    /// 8- and 16-bit `MIN / -1` returns out of range, see [`CheckedOp::Div`].
    /// Returns the function index.
    pub fn get_or_create_floored(&mut self, op: FlooredOp, width: IntWidth) -> u32 {
        assert!(width.is_signed(), "unsigned division isn't floored");
        let wide = width.is_64bit();
        if let Some(&idx) = self.intrinsics.floored.get(&(op, wide)) {
            return idx;
        }

        let ty = if wide { ValType::I64 } else { ValType::I32 };
        let mut code = match op {
            FlooredOp::Div => wasm_encoder::Function::new_with_locals_types([]),
            // 0-1 are params, 2 is the truncated remainder.
            FlooredOp::Rem => wasm_encoder::Function::new_with_locals_types([ty]),
        };
        let mut sink = code.instructions();
        match op {
            FlooredOp::Div => floored_div(&mut sink, wide),
            FlooredOp::Rem => floored_rem(&mut sink, wide),
        }
        sink.end();
        let idx = self.add_function(&FuncType::new([ty, ty], [ty]), code.into_raw_body());
        self.intrinsics.floored.insert((op, wide), idx);
        idx
    }

    /// Get or create the function that computes `op` on two `width` integers,
    /// trapping when the result doesn't fit in `width`.
    /// Returns the function index.
    pub fn get_or_create_checked(&mut self, op: CheckedOp, width: IntWidth) -> u32 {
        if let Some(&idx) = self.intrinsics.checked.get(&(op, width)) {
            return idx;
        }

        let code = match width {
            IntWidth::I64 => checked_i64(op),
            IntWidth::U64 => checked_u64(op),
            IntWidth::I32 | IntWidth::U32 => checked_32(op, width.is_signed()),
            IntWidth::I8 | IntWidth::I16 | IntWidth::U8 | IntWidth::U16 => checked_sub32(op, width),
        };
        let ty = if width.is_64bit() {
            ValType::I64
        } else {
            ValType::I32
        };
        let idx = self.add_function(&FuncType::new([ty, ty], [ty]), code.into_raw_body());
        self.intrinsics.checked.insert((op, width), idx);
        idx
    }

    /// Emit truncation/masking after an i32 operation for sub-32-bit types.
    pub fn emit_truncate(&self, func: &mut StFunction, bb: &mut usize, w: IntWidth) {
        match w {
            IntWidth::I8 => {
                func.instructions(bb).i32_const(24);
                func.instructions(bb).i32_shl();
                func.instructions(bb).i32_const(24);
                func.instructions(bb).i32_shr_s();
            }
            IntWidth::I16 => {
                func.instructions(bb).i32_const(16);
                func.instructions(bb).i32_shl();
                func.instructions(bb).i32_const(16);
                func.instructions(bb).i32_shr_s();
            }
            IntWidth::U8 => {
                func.instructions(bb).i32_const(0xFF);
                func.instructions(bb).i32_and();
            }
            IntWidth::U16 => {
                func.instructions(bb).i32_const(0xFFFF);
                func.instructions(bb).i32_and();
            }
            _ => {} // i32, u32, i64, u64 don't need truncation
        }
    }
}

/// Signed 64-bit arithmetic that traps on overflow.
fn checked_i64(op: CheckedOp) -> wasm_encoder::Function {
    match op {
        CheckedOp::Add => i64_add_checked(),
        CheckedOp::Sub => i64_sub_checked(),
        CheckedOp::Mul => i64_mul_checked(),
        CheckedOp::Div => unreachable!("64-bit division traps natively on overflow"),
    }
}

/// Body of `__starstream_i64_add_checked`, for overflow-checked addition.
fn i64_add_checked() -> wasm_encoder::Function {
    let mut code = wasm_encoder::Function::new_with_locals_types([
        // 0-1 are params, 2+ are here
        ValType::I64,
    ]);
    let sum_local = 2;

    code.instructions().local_get(0); //  [x]
    code.instructions().local_get(1); //  [x, y]
    code.instructions().i64_add();
    code.instructions().local_tee(sum_local); //  [sum]

    // Check for overflow.

    // (x^y)>=0
    code.instructions().local_get(0); //  [sum, x]
    code.instructions().local_get(1); //  [sum, x, y]
    code.instructions().i64_xor(); //  [sum, x^y]
    code.instructions().i64_const(0); //  [sum, x^y, 0]
    code.instructions().i64_ge_s(); //  [sum, (x^y)>=0]

    // (sum^x)<0
    code.instructions().local_get(sum_local); //  [sum, (x^y)>=0, sum]
    code.instructions().local_get(0); //  [sum, (x^y)>=0, sum, x]
    code.instructions().i64_xor(); //  [sum, (x^y)>=0, sum^x]
    code.instructions().i64_const(0); //  [sum, (x^y)>=0, sum^x, 0]
    code.instructions().i64_lt_s(); //  [sum, (x^y)>=0, (sum^x)<0]
    code.instructions().i32_and(); //  [sum, overflow_flag]

    // If overflow_flag != 0, trap.
    code.instructions().i32_const(0); //  [sum, overflow_flag, 0]
    code.instructions().i32_ne(); //  [sum, overflowed?]
    code.instructions().if_(BlockType::Empty); //  [sum]
    code.instructions().unreachable();
    code.instructions().end();

    // Sum is already on stack, add function body end
    code.instructions().end();

    code
}

/// Body of `__starstream_i64_sub_checked`, for overflow-checked subtraction.
fn i64_sub_checked() -> wasm_encoder::Function {
    let mut code = wasm_encoder::Function::new_with_locals_types([
        // 0-1 are params, 2+ are here
        ValType::I64,
    ]);
    let diff_local = 2;

    code.instructions().local_get(0); //  [x]
    code.instructions().local_get(1); //  [x, y]
    code.instructions().i64_sub();
    code.instructions().local_tee(diff_local); //  [diff]

    // Check for overflow.
    // Overflow occurs when subtracting a negative from a positive yields negative,
    // or subtracting a positive from a negative yields positive.
    // In other words: (x^y)<0 && (diff^x)<0

    // (x^y)<0
    code.instructions().local_get(0); //  [diff, x]
    code.instructions().local_get(1); //  [diff, x, y]
    code.instructions().i64_xor(); //  [diff, x^y]
    code.instructions().i64_const(0); //  [diff, x^y, 0]
    code.instructions().i64_lt_s(); //  [diff, (x^y)<0]

    // (diff^x)<0
    code.instructions().local_get(diff_local); //  [diff, (x^y)<0, diff]
    code.instructions().local_get(0); //  [diff, (x^y)<0, diff, x]
    code.instructions().i64_xor(); //  [diff, (x^y)<0, diff^x]
    code.instructions().i64_const(0); //  [diff, (x^y)<0, diff^x, 0]
    code.instructions().i64_lt_s(); //  [diff, (x^y)<0, (diff^x)<0]
    code.instructions().i32_and(); //  [diff, overflow_flag]

    // If overflow_flag != 0, trap.
    code.instructions().i32_const(0); //  [diff, overflow_flag, 0]
    code.instructions().i32_ne(); //  [diff, overflowed?]
    code.instructions().if_(BlockType::Empty); //  [diff]
    code.instructions().unreachable();
    code.instructions().end();

    // Diff is already on stack, add function body end
    code.instructions().end();

    code
}

/// Body of `__starstream_i64_mul_checked`, for overflow-checked multiplication.
fn i64_mul_checked() -> wasm_encoder::Function {
    let mut code = wasm_encoder::Function::new_with_locals_types([
        // 0-1 are params, 2+ are here
        ValType::I64,
        ValType::I64,
        ValType::I64,
    ]);
    let product_local = 2;
    let x_local = 3;
    let y_local = 4;

    // Store parameters in locals for reuse
    code.instructions().local_get(0); //  [x]
    code.instructions().local_tee(x_local); //  [x]
    code.instructions().local_get(1); //  [x, y]
    code.instructions().local_tee(y_local); //  [x, y]
    code.instructions().i64_mul();
    code.instructions().local_tee(product_local); //  [product]

    // Check for overflow.
    // For multiplication overflow detection, we check:
    // 1. If y == 0, no overflow
    // 2. If product / y != x, then overflow occurred
    // Special case: MIN * -1 overflows (since -MIN doesn't fit in i64)

    // Special case: check if x == MIN && y == -1
    code.instructions().local_get(x_local); //  [product, x]
    code.instructions().i64_const(i64::MIN); //  [product, x, MIN]
    code.instructions().i64_eq(); //  [product, x==MIN]
    code.instructions().local_get(y_local); //  [product, x==MIN, y]
    code.instructions().i64_const(-1); //  [product, x==MIN, y, -1]
    code.instructions().i64_eq(); //  [product, x==MIN, y==-1]
    code.instructions().i32_and(); //  [product, (x==MIN && y==-1)]

    // Also check y == MIN && x == -1
    code.instructions().local_get(y_local); //  [product, (x==MIN && y==-1), y]
    code.instructions().i64_const(i64::MIN); //  [product, (x==MIN && y==-1), y, MIN]
    code.instructions().i64_eq(); //  [product, (x==MIN && y==-1), y==MIN]
    code.instructions().local_get(x_local); //  [product, (x==MIN && y==-1), y==MIN, x]
    code.instructions().i64_const(-1); //  [product, (x==MIN && y==-1), y==MIN, x, -1]
    code.instructions().i64_eq(); //  [product, (x==MIN && y==-1), y==MIN, x==-1]
    code.instructions().i32_and(); //  [product, (x==MIN && y==-1), (y==MIN && x==-1)]
    code.instructions().i32_or(); //  [product, overflow_special]

    code.instructions().if_(BlockType::Empty); //  [product]
    code.instructions().unreachable();
    code.instructions().end();

    // Check regular overflow: if y != 0 and product / y != x
    code.instructions().local_get(y_local); //  [product, y]
    code.instructions().i64_const(0); //  [product, y, 0]
    code.instructions().i64_ne(); //  [product, y!=0]
    code.instructions().if_(BlockType::Empty); //  [product]
    // y != 0, so check if product / y == x
    code.instructions().local_get(product_local); //  [product, product]
    code.instructions().local_get(y_local); //  [product, product, y]
    code.instructions().i64_div_s(); //  [product, product/y]
    code.instructions().local_get(x_local); //  [product, product/y, x]
    code.instructions().i64_ne(); //  [product, (product/y)!=x]
    code.instructions().if_(BlockType::Empty); //  [product]
    code.instructions().unreachable();
    code.instructions().end();
    code.instructions().end();

    // Product is already on stack, add function body end
    code.instructions().end();

    code
}

/// Unsigned 64-bit arithmetic that traps on overflow or underflow.
fn checked_u64(op: CheckedOp) -> wasm_encoder::Function {
    // 0-1 are params, 2 is the result.
    let mut code = wasm_encoder::Function::new_with_locals_types([ValType::I64]);
    let result = 2;
    let mut sink = code.instructions();
    match op {
        CheckedOp::Add => {
            // Overflow iff the sum wrapped around below x.
            sink.local_get(0).local_get(1).i64_add().local_tee(result); //  [sum]
            sink.local_get(result).local_get(0).i64_lt_u(); //  [sum, sum<x]
        }
        CheckedOp::Sub => {
            // Underflow iff y > x.
            sink.local_get(0).local_get(1).i64_sub().local_tee(result); //  [diff]
            sink.local_get(0).local_get(1).i64_lt_u(); //  [diff, x<y]
        }
        CheckedOp::Mul => {
            // Overflow iff y != 0 and product / y != x.
            sink.local_get(0).local_get(1).i64_mul().local_tee(result); //  [product]
            sink.local_get(1).i64_eqz(); //  [product, y==0]
            sink.if_(BlockType::Result(ValType::I32));
            sink.i32_const(0);
            sink.else_();
            sink.local_get(result)
                .local_get(1)
                .i64_div_u()
                .local_get(0)
                .i64_ne();
            sink.end(); //  [product, (product/y)!=x]
        }
        CheckedOp::Div => unreachable!("unsigned division can't overflow"),
    }
    sink.if_(BlockType::Empty).unreachable().end(); //  [result]
    sink.end();
    code
}

/// 32-bit arithmetic computed exactly in i64, trapping when the result doesn't
/// fit back in 32 bits.
fn checked_32(op: CheckedOp, signed: bool) -> wasm_encoder::Function {
    // 0-1 are params, 2 is the 64-bit result.
    let mut code = wasm_encoder::Function::new_with_locals_types([ValType::I64]);
    let wide = 2;
    let mut sink = code.instructions();
    for param in [0, 1] {
        sink.local_get(param);
        if signed {
            sink.i64_extend_i32_s();
        } else {
            sink.i64_extend_i32_u();
        }
    }
    match op {
        CheckedOp::Add => sink.i64_add(),
        CheckedOp::Sub => sink.i64_sub(),
        CheckedOp::Mul => sink.i64_mul(),
        CheckedOp::Div => unreachable!("32-bit division traps natively on overflow"),
    };
    sink.local_tee(wide); //  [wide]
    if signed {
        // Doesn't fit iff sign-extending its low half changes it.
        sink.local_get(wide)
            .i32_wrap_i64()
            .i64_extend_i32_s()
            .local_get(wide)
            .i64_ne();
    } else {
        // Doesn't fit iff its high half is nonzero.
        sink.local_get(wide)
            .i64_const(32)
            .i64_shr_u()
            .i64_const(0)
            .i64_ne();
    }
    sink.if_(BlockType::Empty).unreachable().end(); //  [wide]
    sink.i32_wrap_i64();
    sink.end();
    code
}

/// 8- and 16-bit arithmetic computed exactly in i32, trapping when normalizing
/// the result to `width` would change it.
fn checked_sub32(op: CheckedOp, width: IntWidth) -> wasm_encoder::Function {
    // 0-1 are params, 2 is the result.
    let mut code = wasm_encoder::Function::new_with_locals_types([ValType::I32]);
    let result = 2;
    let mut sink = code.instructions();
    match op {
        CheckedOp::Add => {
            sink.local_get(0).local_get(1).i32_add();
        }
        CheckedOp::Sub => {
            sink.local_get(0).local_get(1).i32_sub();
        }
        CheckedOp::Mul => {
            sink.local_get(0).local_get(1).i32_mul();
        }
        CheckedOp::Div => {
            assert!(width.is_signed(), "unsigned division can't overflow");
            floored_div(&mut sink, false);
        }
    }
    sink.local_tee(result); //  [result]
    sink.local_get(result);
    match width {
        IntWidth::I8 => sink.i32_extend8_s(),
        IntWidth::I16 => sink.i32_extend16_s(),
        IntWidth::U8 => sink.i32_const(0xFF).i32_and(),
        IntWidth::U16 => sink.i32_const(0xFFFF).i32_and(),
        _ => unreachable!("{width:?} isn't narrower than 32 bits"),
    };
    sink.local_get(result).i32_ne(); //  [result, normalized!=result]
    sink.if_(BlockType::Empty).unreachable().end(); //  [result]
    sink.end();
    code
}

/// Push the floored quotient of params 0 and 1, as the interpreter's
/// `div_floor` computes it: the truncated quotient, minus one when there's a
/// remainder and the operands' signs differ.
fn floored_div(sink: &mut InstructionSink<'_>, wide: bool) {
    if wide {
        sink.local_get(0).local_get(1).i64_div_s(); //  [q]
        sink.local_get(0)
            .local_get(1)
            .i64_rem_s()
            .i64_const(0)
            .i64_ne(); //  [q, r!=0]
        sink.local_get(0)
            .local_get(1)
            .i64_xor()
            .i64_const(0)
            .i64_lt_s(); //  [q, r!=0, (x^y)<0]
        sink.i32_and().i64_extend_i32_u().i64_sub(); //  [floored q]
    } else {
        sink.local_get(0).local_get(1).i32_div_s(); //  [q]
        sink.local_get(0)
            .local_get(1)
            .i32_rem_s()
            .i32_const(0)
            .i32_ne(); //  [q, r!=0]
        sink.local_get(0)
            .local_get(1)
            .i32_xor()
            .i32_const(0)
            .i32_lt_s(); //  [q, r!=0, (x^y)<0]
        sink.i32_and().i32_sub(); //  [floored q]
    }
}

/// Push the floored remainder of params 0 and 1, using local 2: the truncated
/// remainder, plus the divisor when it's nonzero and their signs differ.
fn floored_rem(sink: &mut InstructionSink<'_>, wide: bool) {
    let r = 2;
    if wide {
        sink.local_get(0).local_get(1).i64_rem_s().local_tee(r); //  [r]
        sink.local_get(1).i64_const(0); //  [r, y, 0]
        sink.local_get(r).i64_const(0).i64_ne(); //  [r, y, 0, r!=0]
        sink.local_get(r)
            .local_get(1)
            .i64_xor()
            .i64_const(0)
            .i64_lt_s(); //  [.., r!=0, (r^y)<0]
        sink.i32_and().select().i64_add(); //  [floored r]
    } else {
        sink.local_get(0).local_get(1).i32_rem_s().local_tee(r); //  [r]
        sink.local_get(1).i32_const(0); //  [r, y, 0]
        sink.local_get(r).i32_const(0).i32_ne(); //  [r, y, 0, r!=0]
        sink.local_get(r)
            .local_get(1)
            .i32_xor()
            .i32_const(0)
            .i32_lt_s(); //  [.., r!=0, (r^y)<0]
        sink.i32_and().select().i32_add(); //  [floored r]
    }
}
